import{_ as t,o as a,c as n,a2 as l}from"./chunks/framework.D5wUhsuj.js";const f=JSON.parse('{"title":"PhyAgentOS Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function o(r,e,d,s,c,g){return a(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="phyagentos-documentation" tabindex="-1">PhyAgentOS Documentation <a class="header-anchor" href="#phyagentos-documentation" aria-label="Permalink to &quot;PhyAgentOS Documentation&quot;">​</a></h1><p>版本 / Version: <strong>1.0.0</strong><br> 实现基线 / Implementation baseline: <strong>Forge Skill binding, Query/Action/Session Tool API, AgentTask recovery, and version-scoped experience, 2026-08-30</strong></p><p>本目录由 PhyAgentOS 开发团队面向用户、运维人员和生态开发者维护。文档只把仓库源码、配置 Schema 与测试实际覆盖的行为称为“当前能力”。<code>plan/</code> 中的设计报告是历史背景，不替代这里的运行契约。</p><p>The PhyAgentOS team maintains this directory for users, operators, and ecosystem developers. A feature is described as current only when it is supported by repository source, configuration schemas, and tests. Historical reports under <code>plan/</code> provide design context but do not replace the operational contract documented here.</p><h2 id="中文" tabindex="-1">中文 <a class="header-anchor" href="#中文" aria-label="Permalink to &quot;中文&quot;">​</a></h2><h3 id="核心手册" tabindex="-1">核心手册 <a class="header-anchor" href="#核心手册" aria-label="Permalink to &quot;核心手册&quot;">​</a></h3><ol><li><a href="/docs/zh/01-framework-introduction">框架介绍</a>：项目定位、控制面边界、执行—证据—判定分离、生命周期与实现范围。</li><li><a href="/docs/zh/02-user-manual">用户手册</a>：安装、Provider/Forge 配置、任务描述、验证模式、Artifact 与排障。</li><li><a href="/docs/zh/03-developer-manual">开发者手册</a>：AgentTask、Tool API client、Skill Runtime、Evidence、Verifier、Recovery 与测试。</li><li><a href="/docs/zh/04-forge-configuration-reference">Forge 配置参考</a>：Forge Tool API、Resource Registry、Evidence、Verification、AgentTask 和 Embodiment 字段。</li><li><a href="/docs/zh/05-agent-experience-and-skill-evolution">Agent 经验与 Skill 自进化</a>：Skill 激活与归因、Episode、Lesson 聚类、Skill 晋升、持久化和安全门控。</li></ol><h3 id="专题手册" tabindex="-1">专题手册 <a class="header-anchor" href="#专题手册" aria-label="Permalink to &quot;专题手册&quot;">​</a></h3><ul><li><a href="/docs/user_manual/README">运行手册</a>：上线前检查、启动顺序、状态观测、取消、重启恢复、备份与故障分层。</li><li><a href="/docs/user_manual/DOCKER">Docker 部署指南</a>：基于 Docker 的快速部署，配合一键脚本完成构建、初始化与运行（仅外连网关，无入站端口）。</li><li><a href="/docs/user_development_guide/README">集成开发指南</a>：Tool/Node/Skill 接入、Bundle 打包与不可变发布、本地闭环、证据源、Provider 和 PAOS 扩展边界。</li><li><a href="/docs/user_development_guide/COMMUNICATION">通信架构</a>：Agent 消息、Forge HTTP/WebSocket、system event、SQLite 与 Artifact 边界。</li><li><a href="/docs/forge/README_zh">Forge Tool API 接入契约</a>：Query/Action/Session、不可变 Skill binding、ToolInvocation、AgentTask、证据、验证、恢复和 Skill Runtime 契约。</li></ul><h3 id="推荐阅读路径" tabindex="-1">推荐阅读路径 <a class="header-anchor" href="#推荐阅读路径" aria-label="Permalink to &quot;推荐阅读路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">目标</th><th style="text-align:left;">建议路径</th></tr></thead><tbody><tr><td style="text-align:left;">先理解项目为何区分执行与任务成功</td><td style="text-align:left;"><a href="/docs/zh/01-framework-introduction">框架介绍</a> → <a href="/docs/forge/README_zh">Forge 接入契约</a></td></tr><tr><td style="text-align:left;">首次部署并跑通 Agent + Forge</td><td style="text-align:left;"><a href="/docs/zh/02-user-manual">用户手册</a> → <a href="/docs/zh/04-forge-configuration-reference">配置参考</a></td></tr><tr><td style="text-align:left;">负责长期在线和故障处理</td><td style="text-align:left;"><a href="/docs/user_manual/README">运行手册</a> → <a href="/docs/user_development_guide/COMMUNICATION">通信架构</a></td></tr><tr><td style="text-align:left;">用 Docker 快速部署</td><td style="text-align:left;"><a href="/docs/user_manual/DOCKER">Docker 部署指南</a></td></tr><tr><td style="text-align:left;">在 Gateway 增加新机器人动作</td><td style="text-align:left;"><a href="/docs/user_development_guide/README">集成开发指南</a> → <a href="/docs/zh/03-developer-manual">开发者手册</a></td></tr><tr><td style="text-align:left;">开发、打包并发布 Forge Skill</td><td style="text-align:left;"><a href="/docs/user_development_guide/README#_5-打包、发布与本地闭环">集成开发指南</a> → <a href="/docs/forge/README_zh">Forge 接入契约</a></td></tr><tr><td style="text-align:left;">修改证据、验证、恢复或持久化</td><td style="text-align:left;"><a href="/docs/zh/03-developer-manual">开发者手册</a> → <a href="/docs/forge/README_zh">Forge 接入契约</a></td></tr><tr><td style="text-align:left;">使用或扩展任务经验、Lesson 与 Skill 自进化</td><td style="text-align:left;"><a href="/docs/zh/05-agent-experience-and-skill-evolution">Agent 经验与 Skill 自进化</a> → <a href="/docs/zh/03-developer-manual">开发者手册</a></td></tr></tbody></table><h2 id="english" tabindex="-1">English <a class="header-anchor" href="#english" aria-label="Permalink to &quot;English&quot;">​</a></h2><h3 id="core-manuals" tabindex="-1">Core manuals <a class="header-anchor" href="#core-manuals" aria-label="Permalink to &quot;Core manuals&quot;">​</a></h3><ol><li><a href="/docs/en/01-framework-introduction">Framework Introduction</a>: positioning, control-plane boundaries, execution/evidence/verdict separation, lifecycle, and implemented scope.</li><li><a href="/docs/en/02-user-manual">User Manual</a>: installation, provider and Forge configuration, task description, verification modes, artifacts, and troubleshooting.</li><li><a href="/docs/en/03-developer-manual">Developer Manual</a>: AgentTask, Tool API client, Skill Runtime, evidence, verifier, recovery, and testing.</li><li><a href="/docs/en/04-forge-configuration-reference">Forge Configuration Reference</a>: exact Forge Tool API, Resource Registry, evidence, verification, AgentTask, and embodiment fields.</li><li><a href="/docs/en/05-agent-experience-and-skill-evolution">Agent Experience and Skill Evolution</a>: Skill activation and attribution, episodes, Lesson clustering, Skill promotion, persistence, and guardrails.</li></ol><h3 id="focused-manuals" tabindex="-1">Focused manuals <a class="header-anchor" href="#focused-manuals" aria-label="Permalink to &quot;Focused manuals&quot;">​</a></h3><ul><li><a href="/docs/user_manual/README_en">Operations Manual</a>: preflight checklist, startup order, observation, cancellation, restart recovery, backup, and failure layers.</li><li><a href="/docs/user_manual/DOCKER_en">Docker Deployment Guide</a>: Docker-based quick deployment with a one-click script for build, init, and run (outbound-only gateway, no inbound port).</li><li><a href="/docs/user_development_guide/README_en">Integration Development Guide</a>: Tool, Node, and Skill integration; Bundle packaging and immutable publication; the local loop; evidence sources; providers; and PAOS extension boundaries.</li><li><a href="/docs/user_development_guide/COMMUNICATION_en">Communication Architecture</a>: Agent messages, Forge HTTP/WebSocket, system events, SQLite, and artifact boundaries.</li><li><a href="/docs/forge/README">Forge Tool API Integration Contract</a>: Query/Action/Session, immutable Skill binding, ToolInvocation, AgentTask, evidence, verification, recovery, and Skill Runtime contracts.</li></ul><h3 id="suggested-reading-paths" tabindex="-1">Suggested reading paths <a class="header-anchor" href="#suggested-reading-paths" aria-label="Permalink to &quot;Suggested reading paths&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Goal</th><th style="text-align:left;">Suggested path</th></tr></thead><tbody><tr><td style="text-align:left;">Understand why execution and task success differ</td><td style="text-align:left;"><a href="/docs/en/01-framework-introduction">Framework Introduction</a> → <a href="/docs/forge/README">Forge Integration Contract</a></td></tr><tr><td style="text-align:left;">Deploy Agent + Forge for the first time</td><td style="text-align:left;"><a href="/docs/en/02-user-manual">User Manual</a> → <a href="/docs/en/04-forge-configuration-reference">Configuration Reference</a></td></tr><tr><td style="text-align:left;">Operate a long-running service</td><td style="text-align:left;"><a href="/docs/user_manual/README_en">Operations Manual</a> → <a href="/docs/user_development_guide/COMMUNICATION_en">Communication Architecture</a></td></tr><tr><td style="text-align:left;">Deploy quickly with Docker</td><td style="text-align:left;"><a href="/docs/user_manual/DOCKER_en">Docker Deployment Guide</a></td></tr><tr><td style="text-align:left;">Add a new robot action in Gateway</td><td style="text-align:left;"><a href="/docs/user_development_guide/README_en">Integration Guide</a> → <a href="/docs/en/03-developer-manual">Developer Manual</a></td></tr><tr><td style="text-align:left;">Develop, package, and publish a Forge Skill</td><td style="text-align:left;"><a href="/docs/user_development_guide/README_en#_5-package-publish-and-close-the-local-loop">Integration Guide</a> → <a href="/docs/forge/README">Forge Integration Contract</a></td></tr><tr><td style="text-align:left;">Change evidence, verification, recovery, or persistence</td><td style="text-align:left;"><a href="/docs/en/03-developer-manual">Developer Manual</a> → <a href="/docs/forge/README">Forge Integration Contract</a></td></tr><tr><td style="text-align:left;">Use or extend task experience, Lessons, or Skill evolution</td><td style="text-align:left;"><a href="/docs/en/05-agent-experience-and-skill-evolution">Agent Experience and Skill Evolution</a> → <a href="/docs/en/03-developer-manual">Developer Manual</a></td></tr></tbody></table><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Term</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;">AgentTask</td><td style="text-align:left;">The PAOS aggregate for a user-visible goal, immutable PlanRevisions, bound calls, evidence, and verification. It does not execute the robot.</td></tr><tr><td style="text-align:left;">PlanRevision</td><td style="text-align:left;">One append-only planning generation inside a stable AgentTask identity.</td></tr><tr><td style="text-align:left;">Query record</td><td style="text-align:left;">The PAOS record of one synchronous Gateway Query bound to an AgentTask.</td></tr><tr><td style="text-align:left;">Forge Skill binding</td><td style="text-align:left;">An immutable snapshot of Skill version, Runtime identity, manifest/workflow hashes, and required live ToolSpecs.</td></tr><tr><td style="text-align:left;">ToolInvocation</td><td style="text-align:left;">The Gateway-owned identity and lifecycle of one asynchronous Action or Session.</td></tr><tr><td style="text-align:left;">Attempt</td><td style="text-align:left;">The Gateway execution attempt identified separately from the ToolInvocation and AgentTask.</td></tr><tr><td style="text-align:left;">Tool execution record</td><td style="text-align:left;">A normalized PAOS Query result or Action/Session invocation reference attached to one PlanRevision.</td></tr><tr><td style="text-align:left;">Evidence Bundle</td><td style="text-align:left;">Validated, workspace-relative artifact references and capture-quality metadata.</td></tr><tr><td style="text-align:left;">Verdict</td><td style="text-align:left;">A structured semantic decision over every success criterion.</td></tr><tr><td style="text-align:left;">Task lineage</td><td style="text-align:left;">One AgentTask and all of its PlanRevisions; only one AgentTask may be non-terminal globally.</td></tr><tr><td style="text-align:left;">Skill activation</td><td style="text-align:left;">An explicit, per-turn binding between a registered workflow Skill and a task; a direct file read is not an activation.</td></tr><tr><td style="text-align:left;">Task episode</td><td style="text-align:left;">One redacted experience record for a completed, semantically verified AgentTask lineage.</td></tr><tr><td style="text-align:left;">Failure observation</td><td style="text-align:left;">A normalized, non-answer-specific description of a workflow-related failure pattern.</td></tr><tr><td style="text-align:left;">Lesson cluster</td><td style="text-align:left;">Independent AgentTask observations grouped by Skill, workflow, and canonical failure pattern.</td></tr><tr><td style="text-align:left;">Scoped Lesson</td><td style="text-align:left;">A validated Lesson with explicit applicability boundaries, dynamically loaded only for a matching activated Skill.</td></tr></tbody></table><h2 id="runtime-and-compatibility-boundaries" tabindex="-1">Runtime and compatibility boundaries <a class="header-anchor" href="#runtime-and-compatibility-boundaries" aria-label="Permalink to &quot;Runtime and compatibility boundaries&quot;">​</a></h2><p>PAOS supports Forge Query, Action, and Session through <code>/tools</code> and <code>/invocations</code>. The Agent-side aggregate is AgentTask, while physical execution remains owned by Gateway ToolInvocation and ToolEndpoint. Skill Runtime manages manifest-v2 bundles and named Dora profiles; it is distinct from the removed Markdown queue Runtime. Existing evolution, experience, verification, and Agent workspace data are read in place. Registry downloads are explicit and digest-verified.</p>',22)])])}const h=t(i,[["render",o]]);export{f as __pageData,h as default};
